const paths={home:'M3 10l9-7 9 7 M5 9v12h5v-7h4v7h5V9',inventory:'M3 4h18v5H3z M5 9v12h14V9 M10 13h4',expenses:'M6 3v18l3-2 3 2 3-2 3 2V3l-3 2-3-2-3 2z M9 9h6 M9 13h6',mileage:'M4 11l2-7h12l2 7 M3 11h18v8H3z M5 19v2 M19 19v2 M6 14h2 M16 14h2',reports:'M3 19l5-6 5 3 7-10 M16 6h4v4 M5 4v4 M3 6h4',tools:'M14 6a6 6 0 00-8-3l4 4-3 3-4-4a6 6 0 008 8l8 8 3-3-8-8z',search:'M20 20l-5-5 M17 10a7 7 0 11-14 0 7 7 0 0114 0',scan:'M3 8V3h5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 7h3v3H7z M14 7h3v3h-3z M7 14h3v3H7z M14 14h3v3h-3z',goals:'M5 22V3 M5 3h14l-3 5 3 5H5',import:'M12 3v12 M7 10l5 5 5-5 M4 20h16',photo:'M3 6h5l2-3h4l2 3h5v15H3z M16 13a4 4 0 11-8 0 4 4 0 018 0',image:'M3 3h18v18H3z M4 18l5-6 4 4 3-3 5 6',clock:'M12 7v5l4 2 M22 12a10 10 0 11-20 0 10 10 0 0120 0',plus:'M12 4v16 M4 12h16',chevron:'M9 5l7 7-7 7',close:'M5 5l14 14 M19 5L5 19',help:'M9 8a3 3 0 116 0c0 3-3 2-3 5 M12 17h.01 M22 12a10 10 0 11-20 0 10 10 0 0120 0',settings:'M12 8a4 4 0 100 8 4 4 0 000-8 M9 3h6l1 3 3 1 2 5-2 4-3 1-1 4H9l-1-4-3-1-2-4 2-5 3-1z',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',tag:'M3 3h9l10 10-9 9L3 12z M7 7h.01'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[n]||paths.inventory}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const seedNames=['Heart Moon Star Green Dress','LEI Brown/Pink Dress','Earthbound Red/Black Dress','Julie Whyte Floral Dress','Ruby Rox Pink Dress','Evolution Blue Short Sleeve Sweater','Newsworthy Paisley Skirt','Vintage Levi’s Denim Jacket','Nike Air Max Sneakers','Ralph Lauren Cable Knit'];
let db;try{db=JSON.parse((localStorage.getItem('store-age-v1')||localStorage.getItem('flippd-clone-v1')))}catch{};db=db||{items:seedNames.map((title,i)=>({id:i+1,title,cost:[8.49,7.99,6.99,7.99,10.99,5.49,4.5,12,15,8][i],price:25+i*3,category:i===8?'Shoes':'Clothing',source:'Thrift Stores',location:'Shelf A',status:i<8?'Unlisted':'Listed',date:'2026-10-15',quantity:1})),expenses:[],trips:[],goals:[],locations:['Shelf A','Bin 01']};
let page=(location.hash.slice(1)||'home'),year='2026',filter='Active',query='',period='7D',reportTab='Monthly',reportMonth=9,tripTab='All';
const save=()=>localStorage.setItem('store-age-v1',JSON.stringify(db));
const toast=s=>{let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',2800)};
function go(p){page=p;query='';location.hash=p;render();window.scrollTo(0,0)}
const btn=(label,action,cls='primary')=>`<button type="${action==='void(0)'?'submit':'button'}" class="${cls}" onclick="${action}">${label}</button>`;
const sales=()=>db.items.filter(i=>i.status==='Sold');
const expenseTotal=()=>db.expenses.filter(x=>x.date.startsWith(year)).reduce((a,x)=>a+ +x.amount,0);
const tripMiles=()=>db.trips.filter(x=>x.date.startsWith(year)).reduce((a,x)=>a+ +x.miles,0);
function render(){if(!['home','inventory','expenses','mileage','reports','tools'].includes(page))page='home';document.querySelector('#app').innerHTML=`<header><div class="brand"><span class="wordmark">Store Age</span><i></i><h1>${page[0].toUpperCase()+page.slice(1)}</h1></div><div class="head-actions"><span>Viewing:</span><select aria-label="Viewing year" onchange="year=this.value;render()">${['2026','2025','2024'].map(y=>`<option ${year===y?'selected':''}>${y}</option>`).join('')}</select><button class="square" aria-label="Help" onclick="help()">${icon('help')}</button><button class="square" aria-label="Settings" onclick="settings()">${icon('settings')}</button></div></header><aside class="sidebar">${btn(icon('plus')+' Add <span style="margin-left:auto;border-left:1px solid #ffffff50;padding-left:17px">⌄</span>','addMenu()','primary add-main')}<hr>${['home','inventory','expenses','mileage','reports','tools'].map(n=>`<a class="nav ${page===n?'active':''}" href="#${n}" onclick="event.preventDefault();go('${n}')">${icon(n)}${n[0].toUpperCase()+n.slice(1)}</a>`).join('')}<footer><span class="key">⌘K</span> Quick actions</footer></aside><main>${({home:home,inventory:inventory,expenses:expenses,mileage:mileage,reports:reports,tools:tools})[page]()}</main>`}
function home(){let u=db.items.filter(i=>i.status==='Unlisted').length,l=db.items.filter(i=>i.status==='Listed').length;let sold=year==='2026'?168+sales().length:0;return `<div class="card stats"><div class="stat-top"><button onclick="filter='Unlisted';go('inventory')"><strong class="yellow">${u}</strong><p>Unlisted</p></button><span>→</span><button onclick="filter='Listed';go('inventory')"><strong>${year==='2026'?90+l:l}</strong><p>Listed</p></button><span>→</span><button onclick="filter='Sold';go('inventory')"><strong class="green">${sold}</strong><p>Sold</p></button></div><div class="stat-bottom"><span>Total Active <b>${90+u+l}</b></span><span>Death Pile <b>0</b></span></div></div><div class="quick">${[['scan','Scan','scan()'],['expenses','Expense',"recordForm('expense')"],['import','Import','importer()'],['search','Research','research()'],['mileage','Mileage',"recordForm('trip')"],['goals','Goals','goals()']].map(([i,t,a])=>btn(icon(i)+t,a,'')).join('')}</div><div class="cols"><div class="stack"><div class="card coach" onclick="coach()"><div class="eyebrow">✦ Your coach</div><div class="row"><h2>What to do next, from your own numbers</h2><span class="green">${icon('chevron')}</span></div></div><div class="card goal"><h3>${db.goals.length?esc(db.goals[0].title):'No active goal'}</h3><p>${db.goals.length?`Target: ${esc(db.goals[0].target)} items · Keep the momentum going`:'You listed 252 items in the last 30 days. Try beating it'}</p><div class="button-row">${btn('Browse challenges','goals()','secondary')}${btn('Custom goal','goalForm()','secondary')}</div></div><div class="card"><h2>Your Performance</h2><div class="row"><span><b class="big green">62%</b> <span class="muted">sell through rate</span></span><span class="badge">Optimal</span></div><p class="muted">Of everything you list, how much you sell</p><div class="progress"><i style="width:62%"></i></div><div class="report-line"><span>Average profit per item</span><b>$6.23</b></div><div class="report-line"><span>Return on investment</span><b class="green">260.2%</b></div></div></div><div class="stack"><div class="card"><div class="row"><h2 style="margin:0">Sales Overview</h2><div class="segment">${['7D','30D','90D'].map(p=>btn(p,`period='${p}';render()`,p===period?'selected':'')).join('')}</div></div><p class="muted" style="margin:25px 0 6px">Last ${period==='7D'?'7':period==='30D'?'30':'90'} days</p><div class="row" style="justify-content:flex-start"><b class="big">${period==='7D'?'$309':period==='30D'?'$1,504':'$4,218'}</b><span class="badge down">↓ 75%</span></div><p class="muted">39 sales · vs $1,225 prior 7 days</p><div class="bars">${[3,7,11,3,7,3,5].map((n,i)=>`<div class="bar">${n}<div style="height:${n*10}px"></div>${['Fri','Sat','Sun','Mon','Tue','Wed','Thu'][i]}</div>`).join('')}</div><div class="sale-foot row"><span><b>Oct 15</b> · <b class="green">$41</b> · 5 sales</span><b class="green">↑ 25%</b></div><div class="report-line"><span>Total net profit</span><b class="green">$1,047.36</b></div>${btn('View reports →',"go('reports')",'plain-link')}</div><div class="card"><div class="row"><h3>Recently added</h3>${btn('View all',"go('inventory')",'plain-link')}</div>${db.items.slice(0,3).map(i=>`<div class="report-line"><span>${esc(i.title)}</span><b>${money(i.cost)}</b></div>`).join('')}</div></div></div>`}
function search(placeholder){return `<label class="search">${icon('search')}<input aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(query)}" oninput="query=this.value;filterContent()"></label>`}
function inventory(){return `${search('Search inventory...')}<div class="toolbar"><div style="display:flex;gap:10px"><select aria-label="Inventory status" onchange="filter=this.value;filterContent()">${['Active','All','Unlisted','Listed','Sold','Written off'].map(x=>`<option ${filter===x?'selected':''}>${x}${x==='Active'?' 100':''}</option>`).join('')}</select><select aria-label="Sort inventory" onchange="sortItems(this.value)"><option>Modified ↓</option><option>Title A–Z</option><option>Cost ↓</option></select></div>${btn(icon('plus')+' Add item','itemForm()','primary')}</div><div class="inventory" id="results">${itemList()}</div>`}
function itemList(){let items=db.items.filter(i=>(filter==='All'||filter==='Active'&&!['Sold','Written off'].includes(i.status)||i.status===filter)&&i.title.toLowerCase().includes(query.toLowerCase()));return items.length?items.map(i=>`<button class="item" onclick="itemForm(${i.id})"><div class="thumb">${i.photo?`<img src="${i.photo}" alt="">`:icon('image')}</div><div><h3>${esc(i.title)}</h3><small>${esc(i.category)}<br>${money(i.cost)}</small></div><div class="item-right"><small>● Oct 15</small><span class="status ${i.status}">${esc(i.status)}</span></div></button>`).join(''):`<div class="empty"><h2>No items found</h2><p>Try another search or add your first item.</p>${btn('+ Add inventory','itemForm()')}</div>`}
function filterContent(){if(page==='inventory')document.querySelector('#results').innerHTML=itemList();else if(page==='expenses')document.querySelector('#results').innerHTML=expenseList();else if(page==='mileage')document.querySelector('#results').innerHTML=tripList()}
function sortItems(v){db.items.sort((a,b)=>v==='Title A–Z'?a.title.localeCompare(b.title):v==='Cost ↓'?b.cost-a.cost:b.id-a.id);filterContent()}
function expenses(){return `${search('Search for expense...')}<div class="row" style="justify-content:flex-end;margin:18px 0"><select aria-label="Sort expenses" onchange="db.expenses.reverse();filterContent()"><option>Date ↓</option><option>Date ↑</option></select>${btn('+ Add Expense',"recordForm('expense')")}</div><div id="results">${expenseList()}</div>`}
function expenseList(){let a=db.expenses.filter(x=>x.date.startsWith(year)&&x.title.toLowerCase().includes(query.toLowerCase()));return a.length?`<div class="summary"><div class="card"><strong>${money(expenseTotal())}</strong>Total Expenses</div><div class="card"><strong>${a.length}</strong>Entries</div></div>${a.map(x=>`<div class="list-record"><div><h3>${esc(x.title)}</h3><span class="muted">${esc(x.category)} · ${x.date}</span></div><div>${money(x.amount)} ${btn('×',`removeRecord('expenses',${x.id})`,'plain-link')}</div></div>`).join('')}`:empty('expenses',`No expenses for ${year} yet`,"Every expense you track lowers your taxable profit. Start with whatever's easiest.",'+ Add an expense',"recordForm('expense')",btn('Snap a receipt',"scan('receipt')",'secondary'))}
function empty(i,h,p,b,a,extra=''){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h2>${h}</h2><p>${p}</p>${btn(b,a)} ${extra}</div>`}
function mileage(){return `<div class="summary"><div class="card"><strong>${tripMiles()}</strong>Total Miles<small>classified</small></div><div class="card"><strong>${money(tripMiles()*.7)}</strong>Deduction<small>illustrative rate · $0.70 / mile</small></div><div class="card"><strong>${db.trips.filter(x=>x.date.startsWith(year)).length}</strong>Entries<small>committed</small></div></div>${search('Search mileage...')}<div class="row"><div class="segment">${['All','Entries','Trips'].map(t=>btn(t,`tripTab='${t}';render()`,tripTab===t?'selected':'')).join('')}</div>${btn('+ Add Mileage',"recordForm('trip')")}</div><div id="results">${tripList()}</div>`}
function tripList(){let a=db.trips.filter(x=>x.date.startsWith(year)&&x.title.toLowerCase().includes(query.toLowerCase())&&(tripTab!=='Entries'||x.type==='Entry')&&(tripTab!=='Trips'||x.type==='Trip'));return a.length?a.map(x=>`<div class="list-record"><div><h3>${esc(x.title)}</h3><span class="muted">${x.date} · ${esc(x.type)} · Business</span></div><div>${x.miles} miles ${btn('×',`removeRecord('trips',${x.id})`,'plain-link')}</div></div>`).join(''):empty('mileage',`No trips for ${year} yet`,'Every business mile you log is a tax deduction. Add a trip by hand to keep your records organized.','+ Add Mileage',"recordForm('trip')")}
function reports(){let factor=year==='2026'&&reportMonth===9?1:0;let gross=1504.21*factor+sales().reduce((a,i)=>a+ +i.price,0),cost=402.52*factor+sales().reduce((a,i)=>a+ +i.cost,0),fees=54.33*factor+sales().reduce((a,i)=>a+ +(i.fees||0),0),net=gross-cost-fees-expenseTotal();let lines=[['Number of Sales',168*factor+sales().length],['Gross Sales',money(gross)],['Cost of Goods Sold',money(cost)],['Shipping Cost','$0.00'],['Platform Fees',money(fees)],['Sales Tax','$0.00'],['Adjustments','$0.00']];return `<div class="card row" style="background:#efefea">${btn('‹',"reportMonth=(reportMonth+11)%12;render()",'square')}<h2 style="margin:0">${new Date(2026,reportMonth).toLocaleString('en',{month:'long'})} ${year}</h2>${btn('›',"reportMonth=(reportMonth+1)%12;render()",'square')}${btn('↓ Export','exportCSV()','square')}</div><div class="report-tabs"><div class="segment">${['Daily','Weekly','Monthly','YTD','Compare'].map(t=>btn(t,`reportTab='${t}';render()`,t===reportTab?'selected':'')).join('')}</div></div><p class="muted" style="text-align:center;font-size:12px">${reportTab} overview · Reference demo sales + your recorded sales</p><div class="cols"><div class="card">${lines.map(([k,v])=>`<div class="report-line"><span>${k}</span><b>${v}</b></div>`).join('')}<div class="report-line total"><span><b>Net Adjusted Profit</b><br><small>after expenses</small></span><b>${money(net)}</b></div><p class="section-label" style="text-align:center">CAPITAL TIED UP</p>${[['Cost of Goods Unsold',money(db.items.filter(i=>i.status!=='Sold').reduce((a,i)=>a+ +i.cost,0))],['All Inventory Cost',money(db.items.reduce((a,i)=>a+ +i.cost,0))],['Cost of Goods Scratched','$0.00']].map(([k,v])=>`<div class="report-line"><span>${k}</span><b>${v}</b></div>`).join('')}${btn('View sales',"filter='Sold';go('inventory')")}</div><div><h2 class="report-section">${icon('reports')} Status Breakdown</h2><div class="card coach"><h3>Sold Items <small class="muted">${168*factor+sales().length} items</small></h3><p class="muted">Net Profit</p><b style="font-size:29px" class="green">${money(net)}</b><p class="muted">Gross Sales: ${money(gross)}<br>Cost of Goods Sold: ${money(cost)}<br>ROI: ${cost?(net/cost*100).toFixed(1):0}% · Avg Profit Margin: ${gross?(net/gross*100).toFixed(1):0}%</p></div><div class="card row" style="margin-top:10px;padding:18px"><span>Unsold Items</span><b>${money(db.items.filter(i=>i.status!=='Sold').reduce((a,i)=>a+ +i.cost,0))}</b></div><h2 class="report-section">Expenses and Mileage</h2><div class="card">${[['Number of Expenses',db.expenses.length],['Total Expenses',money(expenseTotal())],['Miles Driven',tripMiles()],['Mileage Deduction',money(tripMiles()*.7)]].map(([k,v])=>`<div class="report-line"><span>${k}</span><b>${v}</b></div>`).join('')}</div><h2 class="report-section">Tax Reports</h2>${btn('Export records as CSV','exportCSV()','secondary')}</div></div><div class="cols" style="margin-top:30px"><div class="card chart-card"><h2>Sales by Quarter</h2><p class="muted" style="text-align:center">Oct–Nov–Dec · Gross & Net Sales</p><div class="bars" style="height:210px">${[140,0,0].map((n,i)=>`<div class="bar"><div style="height:${n}px"></div>${['Oct','Nov','Dec'][i]}</div>`).join('')}</div></div><div class="card"><h2>Platform Performance</h2><div class="donut"></div>${[['Vinted','$1,203.10'],['Depop','$276.11'],['eBay','$25.00']].map(([p,v])=>`<div class="report-line"><span>${p}</span><b>${v}</b></div>`).join('')}</div></div>`}
function tools(){const group=a=>`<div class="tool-group">${a.map(([i,t,p,action])=>`<button class="tool" onclick="${action}">${icon(i)}<div><b>${t}</b><p>${p}</p></div><span>›</span></button>`).join('')}</div>`;return `<div class="section-label">BUY SMARTER</div>${group([['tools','Profit calculator','Work out fees, shipping and margin before you buy','calculator()'],['search','Price lookup','Research comparable listings on eBay','research()'],['inventory','Bulk purchases','Split a pallet or lot cost across the items inside it','bulk()']])}<div class="section-label">MONEY</div><div class="cols" style="margin:14px 0 28px"><div class="card"><span class="muted">${icon('expenses')} Expenses</span><div class="big">${money(expenseTotal())}</div><p class="muted">${db.expenses.length} logged this year</p>${btn('+ Add Expense',"recordForm('expense')",'secondary')}</div><div class="card"><span class="muted">${icon('mileage')} Mileage</span><div class="big">${money(tripMiles()*.7)}</div><p class="muted">${tripMiles()} miles over ${db.trips.length} tracked drives</p>${btn('+ Add Mileage',"recordForm('trip')",'secondary')}</div></div>${group([['goals','Goals','Set your next goal','goals()']])}<div class="section-label">NEEDS ATTENTION</div>${group([['clock','Aging','Review your oldest listed inventory',"filter='Listed';go('inventory')"],['inventory','Death pile','Written off, clear or relist them',"filter='Written off';go('inventory')"],['help','Records to fix','Check for missing costs and duplicate titles','audit()']])}<div class="section-label">MANAGE</div>${group([['inventory','Storage locations','Name the bins and shelves your stock lives in','locations()'],['tag','Labels','Print SKU labels for your inventory','labels()'],['import','Import / export','Move your data in or out as a CSV backup','importer()']])}`}
function modal(title,body,wide=false){document.querySelector('#modal').innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row"><h2>${title}</h2>${btn(icon('close'),'closeModal()','square')}</div>${body}</div></div>`;document.querySelector('.dialog input')?.focus()}
function closeModal(){document.querySelector('#modal').innerHTML=''}
function field(label,name,value='',type='text',options){return `<label class="field">${label}${options?`<select name="${name}">${options.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${['cost','price','amount','miles','target','quantity'].includes(name)?'min="0" step="0.01"':''} ${name==='title'?'required maxlength="80"':''}>`}</label>`}
let uploadedPhoto='';
function itemForm(id){let i=db.items.find(x=>x.id===id)||{date:'2026-10-15',quantity:1,status:'Unlisted'};uploadedPhoto=i.photo||'';modal(id?'Edit Inventory':'Add Inventory',`<form onsubmit="saveItem(event,${id||0})"><div class="form-grid"><div><div class="photo-upload">${icon('photo')}<p>Add item photos</p><input type="file" accept="image/*" aria-label="Choose item photo" onchange="loadPhoto(this)"><div id="photo-preview">${i.photo?'<img src="'+i.photo+'" style="height:100px;margin-top:15px">':''}</div></div><div class="badge" style="display:inline-block;margin-bottom:24px;color:#9e742d;background:#faf0da">● Let’s get started! · Just acquired</div>${field('Title','title',i.title)}${field('Status','status',i.status,'text',['Unlisted','Listed','Sold','Written off'])}</div><div><div class="form-grid">${field('Cost ($)','cost',i.cost||0,'number')}${field('Quantity','quantity',i.quantity,'number')}</div>${field('Date Acquired','date',i.date,'date')}${field('Category','category',i.category||'Clothing','text',['Clothing','Shoes','Electronics','Books','Home','Collectibles','Unspecified'])}${field('Source','source',i.source||'Thrift Stores','text',['Thrift Stores','Garage Sale','Online','Wholesale','Unknown'])}${field('Storage Location','location',i.location,'text',db.locations)}${field('Estimated List / Sale Price ($)','price',i.price||0,'number')}${field('Platform Fees ($)','fees',i.fees||0,'number')}</div></div>${btn(id?'Save changes':'+ ADD','void(0)')}<p class="small-note">Changes are saved on this browser.</p>${id?btn('Delete item',`deleteItem(${id})`,'plain-link'):''}</form>`,true)}
function loadPhoto(input){let f=input.files[0];if(!f)return;if(f.size>4000000)return toast('Choose an image smaller than 4 MB');let r=new FileReader();r.onload=()=>{uploadedPhoto=r.result;document.querySelector('#photo-preview').innerHTML=`<img src="${r.result}" style="height:100px;margin-top:15px">`};r.readAsDataURL(f)}
function saveItem(e,id){e.preventDefault();let values=Object.fromEntries(new FormData(e.target));values.id=id||Date.now();values.photo=uploadedPhoto;for(let k of ['cost','price','quantity','fees'])values[k]=Number(values[k]);if(id)db.items[db.items.findIndex(x=>x.id===id)]=values;else db.items.unshift(values);save();closeModal();go('inventory');toast(id?'Item updated':'Inventory added')}
function deleteItem(id){db.items=db.items.filter(x=>x.id!==id);save();closeModal();render();toast('Item deleted')}
function recordForm(type){let exp=type==='expense';modal(exp?'Add Expense':'Add Mileage',`<form onsubmit="saveRecord(event,'${type}')">${field(exp?'Description':'Trip purpose','title')}${field('Date','date','2026-10-15','date')}${exp?field('Amount ($)','amount','','number')+field('Category','category','Shipping Supplies','text',['Shipping Supplies','Office Supplies','Software','Storage','Travel','Other']):field('Distance (miles)','miles','','number')+field('Record type','type','Trip','text',['Trip','Entry'])}${btn(exp?'Save expense':'Save mileage','void(0)')}</form>`)}
function saveRecord(e,type){e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(!(Number(v.amount||v.miles)>0))return toast('Enter an amount greater than zero');v.id=Date.now();db[type==='expense'?'expenses':'trips'].unshift(v);save();closeModal();go(type==='expense'?'expenses':'mileage');toast('Record saved')}
function removeRecord(key,id){db[key]=db[key].filter(x=>x.id!==id);save();render();toast('Record removed')}
function addMenu(){modal('Quick actions',`<div class="tool-group">${[['inventory','Inventory','itemForm()'],['expenses','Expense',"recordForm('expense')"],['mileage','Mileage',"recordForm('trip')"]].map(([i,t,a])=>`<button class="tool" onclick="${a}">${icon(i)}<b>Add ${t}</b><span>›</span></button>`).join('')}</div>`)}
function calculator(){modal('Profit calculator',`<form oninput="calc()"><div class="form-grid">${field('Sale price ($)','sale',50,'number')}${field('Purchase cost ($)','buy',10,'number')}${field('Platform fee (%)','fee',13,'number')}${field('Shipping cost ($)','shipping',5,'number')}</div><div class="card" id="calc-result"></div></form>`);calc()}
function calc(){let f=document.querySelector('.dialog form'),v=Object.fromEntries(new FormData(f)),profit=+v.sale- +v.buy- +v.shipping-(+v.sale* +v.fee/100);document.querySelector('#calc-result').innerHTML=`<div class="muted">Estimated net profit</div><div class="big green">${money(profit)}</div><p class="muted">Margin: ${+v.sale?(profit/v.sale*100).toFixed(1):0}% · ROI: ${+v.buy?(profit/v.buy*100).toFixed(1):0}%</p>`}
function goals(){modal('Your goals',`<p class="muted">Build your next milestone, one listing at a time.</p>${db.goals.map(g=>`<div class="card"><h3>${esc(g.title)}</h3><p class="muted">Target: ${esc(g.target)} items</p></div>`).join('')}<div class="tool-group"><button class="tool" onclick="goalForm('List 30 items',30)">${icon('goals')}<div><b>30-day listing challenge</b><p>List one item every day.</p></div><span>›</span></button></div>${btn('Create custom goal','goalForm()')}`)}
function goalForm(title='',target=50){modal('Create a goal',`<form onsubmit="event.preventDefault();db.goals.unshift(Object.fromEntries(new FormData(event.target)));save();closeModal();render();toast('Goal created')">${field('Goal name','title',title)}${field('Target items','target',target,'number')}${btn('Set goal','void(0)')}</form>`)}
function coach(){modal('Your coach',`<p class="eyebrow" style="margin-top:25px">Inventory insights</p><h3>Start with the items you already own.</h3><p class="muted">You have ${db.items.filter(i=>i.status==='Unlisted').length} unlisted items. Photograph and list these before buying more stock.</p><div class="card"><b>Next step</b><p class="muted">Set aside 20 minutes and list three items. Use the profit calculator to check your target margin.</p></div>${btn('Review unlisted items',"closeModal();filter='Unlisted';go('inventory')")}<p class="small-note">This local coach uses simple rules based on your inventory.</p>`)}
function research(){modal('Price lookup',`<p class="muted">Search eBay’s completed and sold listings to compare prices.</p><form onsubmit="event.preventDefault();window.open('https://www.ebay.com/sch/i.html?_nkw='+encodeURIComponent(this.title.value)+'&LH_Sold=1&LH_Complete=1','_blank','noopener')">${field('Product name or barcode','title')}${btn('Search sold listings ↗','void(0)')}</form>`)}
function scan(kind){modal(kind==='receipt'?'Receipt entry':'Scan a barcode',`<p class="muted">Automatic camera recognition requires an external service. Enter a barcode to research an item, or attach a photo when adding inventory.</p>${btn('Enter product details','itemForm()')}${btn('Add receipt details',"recordForm('expense')",'plain-link')}`)}
function bulk(){modal('Bulk purchase calculator',`<form oninput="document.querySelector('#bulk-result').textContent=money(this.total.value/Math.max(1,this.count.value))+' per item'"><div class="form-grid">${field('Total lot cost ($)','total',100,'number')}${field('Number of items','count',20,'number')}</div><div class="card big green" id="bulk-result">$5.00 per item</div></form>`)}
function audit(){let missing=db.items.filter(x=>!x.cost||db.items.filter(i=>i.title===x.title).length>1);modal('Records to fix',`<p class="muted">Checked ${db.items.length} inventory records for missing costs and duplicate titles.</p>${missing.length?missing.map(x=>`<button class="tool" onclick="itemForm(${x.id})">${esc(x.title)} ${icon('chevron')}</button>`).join(''):'<div class="card"><h3 class="green">✓ All clear</h3><p class="muted">No missing costs or duplicate titles found.</p></div>'}`)}
function locations(){modal('Storage locations',`<div class="tool-group">${db.locations.map(x=>`<div class="tool">${icon('inventory')} ${esc(x)}</div>`).join('')}</div><form onsubmit="event.preventDefault();db.locations.push(this.title.value);save();locations()">${field('New location','title')}${btn('+ Add location','void(0)')}</form>`)}
function labels(){modal('Inventory labels',`<p class="muted">Print simple title and SKU labels.</p><div id="label-content">${db.items.map(i=>`<div style="display:inline-block;border:1px solid #7b897e;padding:15px;margin:5px;width:220px"><b>${esc(i.title)}</b><p>SKU ${i.id}<br>${esc(i.location||'Unassigned')}</p></div>`).join('')}</div>${btn('Print labels','printLabels()')}`)}
function printLabels(){let w=window.open('','_blank');w.document.write('<html><title>Inventory labels</title><body>'+document.querySelector('#label-content').innerHTML+'</body></html>');w.document.close();w.print()}
function exportCSV(){let rows=[['Title','Cost','Price','Category','Status','Date','Source','Location'],...db.items.map(i=>[i.title,i.cost,i.price,i.category,i.status,i.date,i.source,i.location])];let blob=new Blob([rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='store-age-inventory.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Inventory exported')}
function importer(){modal('Import / export',`<p class="muted">Export your inventory or import a CSV with Title, Cost, Price, Category and Status columns.</p>${btn('↓ Export inventory CSV','exportCSV()')}<label class="photo-upload" style="display:block">Import inventory CSV<input type="file" accept=".csv" onchange="importCSV(this)"></label><p class="small-note">Imported records are added to your current inventory.</p>`)}
function importCSV(input){let file=input.files[0];if(!file)return;let r=new FileReader();r.onload=()=>{try{let rows=parseCSV(String(r.result));let head=rows.shift().map(h=>h.toLowerCase().trim());if(!head.includes('title'))throw Error('CSV needs a Title column');let imported=rows.filter(r=>r[head.indexOf('title')]?.trim()).map((r,i)=>({id:Date.now()+i,title:r[head.indexOf('title')],cost:+r[head.indexOf('cost')]||0,price:+r[head.indexOf('price')]||0,category:r[head.indexOf('category')]||'Unspecified',status:['Unlisted','Listed','Sold','Written off'].includes(r[head.indexOf('status')])?r[head.indexOf('status')]:'Unlisted',date:r[head.indexOf('date')]||'2026-10-15',source:r[head.indexOf('source')]||'Unknown',location:r[head.indexOf('location')]||'',quantity:1}));db.items.unshift(...imported);save();closeModal();filter='All';go('inventory');toast(imported.length+' items imported')}catch(e){toast(e.message)}};r.readAsText(file)}
function parseCSV(s){let rows=[],row=[],cell='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){cell+='"';i++}else q=!q}else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}return rows}
function help(){modal('Welcome to your workspace',`<p class="muted">An open-source workspace for your resale business.</p><div class="tool-group"><div class="tool">${icon('inventory')}<div><b>Track inventory</b><p>Add items, change their status and record a sale price.</p></div></div><div class="tool">${icon('reports')}<div><b>See your numbers</b><p>Track expenses, mileage and inventory profit.</p></div></div></div><p class="small-note">Reference dashboard figures are demo data. Your changes are stored locally in this browser. Marketplace sync, AI recognition and account services are not connected.</p>`)}
function settings(){modal('Settings',`<p class="muted">Workspace preferences</p><div class="card"><h3>Local workspace</h3><p class="muted">Your inventory, expenses and mileage are saved automatically in this browser.</p>${btn('Export inventory backup','exportCSV()','secondary')}</div><p class="small-note">Currency: USD · Theme: Paper & Cobalt · Demo reference year: 2026</p>`)}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();addMenu()}});render();
